(r, big) => {
    // a solved grid from a shifted pattern, then digits relabelled, rows and columns shuffled within bands
    const digits = r.shuffle(["1", "2", "3", "4", "5", "6", "7", "8", "9"]);
    const order = () => [].concat(...r.shuffle([0, 1, 2]).map(b => r.shuffle([0, 1, 2]).map(x => b * 3 + x)));
    const rows = order(), cols = order();
    const keep = big ? 0.6 : r.pick([0.15, 0.4, 0.7, 1]);
    const b = rows.map(i => cols.map(j => r.bool(keep) ? digits[(i * 3 + Math.floor(i / 3) + j) % 9] : "."));
    const errors = r.int(0, 2);
    for (let e = 0; e < errors; e++) b[r.int(0, 8)][r.int(0, 8)] = String(r.int(1, 9));
    return [b];
  }

