function isValidBoard(board: string[][]): boolean {
  const unitOk = (cells: string[]): boolean => {
    const seen = new Set<string>();
    for (const d of cells) {
      if (d === ".") continue;
      if (seen.has(d)) return false;
      seen.add(d);
    }
    return true;
  };
  for (let i = 0; i < 9; i++) {
    const row: string[] = [], col: string[] = [], box: string[] = [];
    for (let j = 0; j < 9; j++) {
      row.push(board[i][j]);
      col.push(board[j][i]);
      // box i, cell j: top-left corner (3·floor(i/3), 3·(i%3)), then j walks it row by row
      box.push(board[3 * Math.floor(i / 3) + Math.floor(j / 3)][3 * (i % 3) + (j % 3)]);
    }
    if (!unitOk(row) || !unitOk(col) || !unitOk(box)) return false;
  }
  return true;
}

