            digits = [d for d in cells if d != "."]
            return len(digits) == len(set(digits))

        for i in range(9):
            row = board[i]
            col = [board[j][i] for j in range(9)]
            # box i, cell j: top-left corner (3*(i//3), 3*(i%3)), then j walks it row by row
            box = [board[3 * (i // 3) + j // 3][3 * (i % 3) + j % 3] for j in range(9)]
            if not (unit_ok(row) and unit_ok(col) and unit_ok(box)):
                return False
        return True

